import React, { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";

import { useAppContext } from "../context/AppContext";
import api from "../services/api";

// SAFE TOKEN PARSE
const getRoleFromToken = (token) => {
  try {
    if (!token) return null;

    const base64 = token.split(".")[1];
    if (!base64) return null;

    const payload = JSON.parse(atob(base64));
    return payload?.role || null;
  } catch {
    return null;
  }
};

const Login = () => {
  const navigate = useNavigate();
  const { preloadAfterLogin } = useAppContext();

  const [formData, setFormData] = useState({
    username: "",
    password: "",
  });

  const [error, setError] = useState("");
  const [loading, setLoading] = useState(false);
  const [showPassword, setShowPassword] = useState(false);

  // ✅ AUTO REDIRECT (SAFE)
  useEffect(() => {
    const token = localStorage.getItem("token");

    if (token && token !== "null" && token !== "undefined") {
      const role = getRoleFromToken(token);

      if (role === "admin") navigate("/admin", { replace: true });
      else if (role === "client") navigate("/client", { replace: true });
      else {
        // ❌ invalid token cleanup
        localStorage.removeItem("token");
        localStorage.removeItem("user");
      }
    }
  }, [navigate]);

  const handleChange = (e) => {
    setFormData((prev) => ({
      ...prev,
      [e.target.name]: e.target.value,
    }));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    setError("");
    setLoading(true);

    try {
      const res = await api.post("/auth/login", formData);

      // ✅ TOKEN SAFE EXTRACT
      const token = res?.data?.access_token;

      if (!token) {
        throw new Error("Invalid login response");
      }

      const role = getRoleFromToken(token);

      if (!role) {
        throw new Error("Invalid token");
      }

      const userData = res.data.user || {
        username: formData.username,
        role,
      };

      // ✅ CLEAR OLD TOKEN (IMPORTANT)
      localStorage.removeItem("token");
      localStorage.removeItem("user");

      // ✅ SAVE NEW TOKEN
      localStorage.setItem("token", token);
      localStorage.setItem("user", JSON.stringify(userData));

      // ✅ NAVIGATION
      if (role === "admin") {
        navigate("/admin", { replace: true });
      } else {
        navigate("/client", { replace: true });
      }

      // ✅ PREFETCH (NON-BLOCKING)
      setTimeout(() => {
        preloadAfterLogin?.(role);
      }, 0);

    } catch (err) {
      console.log("LOGIN ERROR:", err);

      const msg =
        typeof err.response?.data?.detail === "object"
          ? JSON.stringify(err.response.data.detail)
          : err.response?.data?.detail ||
            err.message ||
            "Server not reachable";

      setError(msg);

      // ❌ CLEANUP ON ERROR
      localStorage.removeItem("token");
      localStorage.removeItem("user");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="auth-shell auth-login">
      <div className="auth-hero">
        <div className="auth-shape shape-one" />
        <div className="auth-shape shape-two" />
        <div className="auth-brand">
          <span className="auth-brand-mark">CB</span>
          <span>Campus Booking System</span>
        </div>

        <div className="auth-hero-content">
          <p className="eyebrow">Campus Resource Platform</p>
          <h1>Campus Booking System</h1>
          <p>
            Fast, secure and intelligent campus resource booking platform.
          </p>

          <ul className="auth-feature-list" aria-label="Platform features">
            <li><span>✓</span>Real-time availability</li>
            <li><span>✓</span>Fast approval workflow</li>
            <li><span>✓</span>Resource tracking</li>
            <li><span>✓</span>Booking history</li>
          </ul>
        </div>
      </div>

      <div className="auth-card">
        <div className="auth-card-header">
          <span className="auth-card-icon">→</span>
          <div>
            <h2>Welcome back</h2>
            <p>Sign in to continue to your booking dashboard.</p>
          </div>
        </div>

        <form onSubmit={handleSubmit} className="auth-form">
          <label>
            <span>Username or email</span>
            <div className="auth-input-wrap">
              <span className="auth-input-icon" aria-hidden="true">
                <svg viewBox="0 0 24 24" role="img">
                  <path d="M20 21a8 8 0 0 0-16 0" />
                  <circle cx="12" cy="7" r="4" />
                </svg>
              </span>
              <input
                type="text"
                name="username"
                value={formData.username}
                onChange={handleChange}
                placeholder="Enter username or email"
                required
              />
            </div>
          </label>

          <label>
            <span>Password</span>
            <div className="auth-input-wrap">
              <span className="auth-input-icon" aria-hidden="true">
                <svg viewBox="0 0 24 24" role="img">
                  <rect x="4" y="11" width="16" height="9" rx="2" />
                  <path d="M8 11V8a4 4 0 0 1 8 0v3" />
                </svg>
              </span>
              <input
                type={showPassword ? "text" : "password"}
                name="password"
                value={formData.password}
                onChange={handleChange}
                placeholder="Enter password"
                required
              />
              <button
                type="button"
                className="password-toggle"
                onClick={() => setShowPassword((prev) => !prev)}
                aria-label={showPassword ? "Hide password" : "Show password"}
              >
                {showPassword ? (
                  <svg viewBox="0 0 24 24" role="img">
                    <path d="m3 3 18 18" />
                    <path d="M10.6 10.6A2 2 0 0 0 13.4 13.4" />
                    <path d="M9.9 4.2A10.8 10.8 0 0 1 12 4c5 0 9 5 9 8a9.2 9.2 0 0 1-2.3 3.7" />
                    <path d="M6.1 6.1C4.2 7.5 3 9.8 3 12c0 3 4 8 9 8a10.7 10.7 0 0 0 4-.8" />
                  </svg>
                ) : (
                  <svg viewBox="0 0 24 24" role="img">
                    <path d="M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12Z" />
                    <circle cx="12" cy="12" r="3" />
                  </svg>
                )}
              </button>
            </div>
          </label>

          {/* ✅ ERROR SAFE */}
          {error && (
            <div className="alert error">
              {typeof error === "object"
                ? JSON.stringify(error)
                : error}
            </div>
          )}

          <button
            type="submit"
            className="primary-button auth-button"
            disabled={loading}
          >
            {loading ? (
              <>
                <span className="button-spinner" />
                Logging in...
              </>
            ) : (
              "Login"
            )}
          </button>
        </form>
      </div>
    </div>
  );
};

export default Login;
